## 4. Data Models and Schemas

### 4.1 Core Data Models

#### 4.1.1 Person Model
```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "id": {
      "type": "integer",
      "description": "Unique person identifier"
    },
    "confidence": {
      "type": "number",
      "minimum": 0.0,
      "maximum": 1.0,
      "description": "Detection confidence score"
    },
    "bounding_box": {
      "$ref": "#/definitions/BoundingBox"
    },
    "keypoints": {
      "type": "array",
      "items": {"$ref": "#/definitions/Keypoint"}
    },
    "dense_pose": {
      "$ref": "#/definitions/DensePose"
    },
    "tracking_info": {
      "$ref": "#/definitions/TrackingInfo"
    }
  },
  "required": ["id", "confidence", "bounding_box", "keypoints"]
}
```

#### 4.1.2 Keypoint Model
```json
{
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "enum": ["nose", "left_eye", "right_eye", "left_ear", "right_ear", 
               "left_shoulder", "right_shoulder", "left_elbow", "right_elbow",
               "left_wrist", "right_wrist", "left_hip", "right_hip",
               "left_knee", "right_knee", "left_ankle", "right_ankle"]
    },
    "x": {"type": "number"},
    "y": {"type": "number"},
    "confidence": {
      "type": "number",
      "minimum": 0.0,
      "maximum": 1.0
    },
    "visible": {"type": "boolean"}
  },
  "required": ["name", "x", "y", "confidence"]
}
```

#### 4.1.3 Dense Pose Model
```json
{
  "type": "object",
  "properties": {
    "body_parts": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "part_id": {"type": "integer"},
          "part_name": {"type": "string"},
          "uv_coordinates": {
            "type": "array",
            "items": {
              "type": "array",
              "items": {"type": "number"},
              "minItems": 2,
              "maxItems": 2
            }
          },
          "confidence": {
            "type": "number",
            "minimum": 0.0,
            "maximum": 1.0
          }
        },
        "required": ["part_id", "part_name", "uv_coordinates", "confidence"]
      }
    }
  }
}
```

