    const persister = this.persistenceStrategies[strategy];

    // Create session snapshot
    const snapshot = {
      sessionId,
      timestamp: Date.now(),
      state: await persister.serialize(state),
      metadata: {
        strategy,
        version: '3.0.0',
        checksum: await this.computeChecksum(state)
      }
