      namespace: 'sessions',
      key: `session:${sessionId}:snapshot`,
      value: JSON.stringify(snapshot),
      ttl: 30 * 24 * 60 * 60 * 1000 // 30 days
    });

    // Store session index
    await this.updateSessionIndex(sessionId, snapshot.metadata);

    return snapshot;
  }

  // Restore session state
