    // Retrieve snapshot
    const snapshotData = await mcp.memory_usage({
      action: 'retrieve',
      namespace: 'sessions',
      key: `session:${sessionId}:snapshot`
    });

    if (!snapshotData) {
      throw new Error(`Session ${sessionId} not found`);
