    if (!isValid) {
      throw new Error(`Session ${sessionId} checksum verification failed`);
    }

    // Deserialize state
    const persister = this.persistenceStrategies[snapshot.metadata.strategy];
    return persister.deserialize(snapshot.state);
  }

  // Incremental session sync
